{
  "explanation": "With 100% annual interest compounded n times per year, your $1 becomes (1 + 1/n)ⁿ after one year: yearly compounding gives $2.00, monthly gives about $2.61, and daily gives about $2.7146. The surprise is that this doesn't blow up — it converges to a finite limit, e ≈ 2.71828, which is exactly what continuous compounding yields. The graph plots your final balance against n on a logarithmic scale, so you can drag the yellow dot (or slider) from n = 1 to n = 1000 and watch the value lock onto the horizontal line at e.",
  "manimCode": "const f = (n) => Math.pow(1 + 1 / n, n);

// Axes: x-axis is log10(n), so x=0 is n=1 and x=3 is n=1000
const ax = new Axes({
  xRange: [0, 3, 1],
  yRange: [1.9, 2.9, 0.2],
  xLength: 9,
  yLength: 4.4,
  tips: false
});
ax.moveTo([-0.8, -0.4, 0]);

const formula = new MathTex({ latex: '\\lim_{n \\to \\infty} \\left(1 + \\frac{1}{n}\\right)^{n} = e \\approx 2.71828' });
await formula.waitForRender();
formula.scale(0.9);
formula.moveTo([-0.8, 3.2, 0]);

await scene.play(new Create(ax));
await scene.play(new Write(formula));

const curve = ax.plot((x) => f(Math.pow(10, x)), { color: BLUE, xRange: [0, 3], numSamples: 300 });
await scene.play(new Create(curve));

// Horizontal line at e — the continuous-compounding limit
const eLine = new Line({ start: ax.c2p(0, Math.E), end: ax.c2p(3, Math.E), color: YELLOW });
eLine.setStrokeWidth(2);
const eLabel = new MathTex({ latex: 'e \\approx 2.71828' });
await eLabel.waitForRender();
eLabel.scale(0.8);
eLabel.moveTo(ax.c2p(0.45, Math.E));
eLabel.shift(scaleVec(0.35, UP));
await scene.play(new AnimationGroup([new FadeIn(eLine), new FadeIn(eLabel)]));

// X tick labels: 10^0 ... 10^3
for (let i = 0; i <= 3; i++) {
  const tl = new MathTex({ latex: '10^{' + i + '}' });
  await tl.waitForRender();
  tl.scale(0.7);
  tl.moveTo(ax.c2p(i, 1.9));
  tl.shift(scaleVec(0.35, DOWN));
  scene.add(tl);
}
const xCap = new Text({ text: 'compounds per year n (log scale)', color: GRAY, fontSize: 20 });
xCap.moveTo(ax.c2p(1.5, 1.9));
xCap.shift(scaleVec(0.75, DOWN));
scene.add(xCap);

// Readout label (Text is immutable, so we remove/recreate it on updates)
let readout = new Text({ text: 'n = 1 (yearly)  ->  $2.000000', color: WHITE, fontSize: 24 });
readout.moveTo([-4.1, 2.4, 0]);
scene.add(readout);

function setReadout(str) {
  const pos = readout.getCenter();
  scene.remove(readout);
  readout = new Text({ text: str, color: WHITE, fontSize: 24 });
  readout.moveTo(pos);
  scene.add(readout);
}

// Milestone dots — hover to inspect classic compounding schedules
const milestones = [[1, 'yearly'], [2, 'semi-annual'], [4, 'quarterly'], [12, 'monthly'], [365, 'daily']];
for (const pair of milestones) {
  const m = pair[0];
  const name = pair[1];
  const md = new Dot({ point: ax.c2p(Math.log10(m), f(m)), color: GRAY });
  scene.add(md);
  makeHoverable(md, scene, {
    hoverColor: YELLOW,
    onHoverStart: () => setReadout('n = ' + m + ' (' + name + ')  ->  $' + f(m).toFixed(6)),
    onHoverEnd: () => refreshDot()
  });
}

// Main draggable dot riding the curve
let logN = 0;
const dot = new Dot({ point: ax.c2p(0, f(1)), color: YELLOW });
scene.add(dot);

const x0pix = ax.c2p(0, 0)[0];
const x3pix = ax.c2p(3, 0)[0];

function refreshDot() {
  const n = Math.pow(10, logN);
  dot.moveTo(ax.c2p(logN, f(n)));
  const nDisp = String(Math.round(n * 100) / 100);
  setReadout('n = ' + nDisp + '  ->  $' + f(n).toFixed(6));
}

makeDraggable(dot, scene, {
  constrainX: [x0pix, x3pix],
  onDrag: (mob, pos) => {
    const t = (pos[0] - x0pix) / (x3pix - x0pix) * 3;
    logN = Math.min(3, Math.max(0, t));
    refreshDot();
  }
});

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'log10(n)', min: 0, max: 3, value: 0, step: 0.01, onChange: (v) => { logN = v; refreshDot(); } });
controls.addButton({ label: 'Jump to n = 1000', onClick: () => { logN = 3; refreshDot(); } });

await scene.wait(999999);"
}

